1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type ScenarioResult = {
41	  results: unknown[];
42	};
43	
44	const PROCESSING_FEE = 5;
45	
46	type ItemTypeSpec = {
47	  basePremium: number;
48	  insuranceValue: number;
49	};
50	
51	const ITEM_CATALOGUE: Record<string, ItemTypeSpec> = {
52	  sword: { basePremium: 100, insuranceValue: 1000 },
53	  amulet: { basePremium: 60, insuranceValue: 600 },
54	  staff: { basePremium: 80, insuranceValue: 800 },
55	  potion: { basePremium: 40, insuranceValue: 400 },
56	  rune: { basePremium: 25, insuranceValue: 250 },
57	  moonstone: { basePremium: 25, insuranceValue: 250 },
58	};
59	
60	// Most money figures in a policy are "some value, totalled over the items".
61	const sumOver = (items: Item[], valueOf: (item: Item) => number): number =>
62	  items.reduce((total, item) => total + valueOf(item), 0);
63	
64	const catalogueEntryFor = (item: Item): ItemTypeSpec => {
65	  const spec = ITEM_CATALOGUE[item.type];
66	
67	  if (spec === undefined) {
68	    throw new Error(`unknown item type: ${item.type}`);
69	  }
70	
71	  return spec;
72	};
73	
74	const basePremiumOf = (item: Item): number =>
75	  catalogueEntryFor(item).basePremium;
76	
77	const insuranceValueOf = (item: Item): number =>
78	  catalogueEntryFor(item).insuranceValue;
79	
80	const BLOCK_SIZE = 3;
81	const BLOCK_BASE_PREMIUM = 60;
82	
83	const itemsGroupedByType = (items: Item[]): Item[][] => [
84	  ...items
85	    .reduce(
86	      (groupsByType, item) =>
87	        groupsByType.set(item.type, [
88	          ...(groupsByType.get(item.type) ?? []),
89	          item,
90	        ]),
91	      new Map<string, Item[]>(),
92	    )
93	    .values(),
94	];
95	
96	const formsABlock = (itemsAlike: Item[]): boolean =>
97	  itemsAlike.length === BLOCK_SIZE;
98	
99	const basePremiumOfItemsAlike = (itemsAlike: Item[]): number =>
100	  formsABlock(itemsAlike)
101	    ? BLOCK_BASE_PREMIUM
102	    : sumOver(itemsAlike, basePremiumOf);
103	
104	const totalBasePremiumOf = (items: Item[]): number =>
105	  itemsGroupedByType(items).reduce(
106	    (total, itemsAlike) => total + basePremiumOfItemsAlike(itemsAlike),
107	    0,
108	  );
109	
110	// The MHPCO rounds whichever way costs it least: premiums up, payouts down.
111	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
112	
113	const roundedDownInMHPCOsFavour = (payout: number): number =>
114	  Math.floor(payout);
115	
116	type Rule<Subject> = {
117	  appliesTo: (subject: Subject) => boolean;
118	  rate: number;
119	};
120	
121	const totalRateOf = <Subject,>(
122	  rules: Rule<Subject>[],
123	  subject: Subject,
124	): number =>
125	  rules.reduce(
126	    (rate, rule) => (rule.appliesTo(subject) ? rate + rule.rate : rate),
127	    0,
128	  );
129	
130	const CURSE_SURCHARGE_RATE = 0.5;
131	const HIGH_ENCHANTMENT_THRESHOLD = 5;
132	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
133	
134	const ITEM_SURCHARGE_RULES: Rule<Item>[] = [
135	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
136	  {
137	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
138	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
139	  },
140	];
141	
142	const itemSurchargeOf = (item: Item): number =>
143	  basePremiumOf(item) * totalRateOf(ITEM_SURCHARGE_RULES, item);
144	
145	const totalItemSurchargeOf = (items: Item[]): number =>
146	  sumOver(items, itemSurchargeOf);
147	
148	const LOYALTY_YEARS_THRESHOLD = 2;
149	const LOYALTY_DISCOUNT_RATE = -0.2;
150	
151	// Levied on every policy, follow-ups included — not only on a customer's first.
152	const INSURANCE_SURCHARGE_RATE = 0.1;
153	
154	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
155	
156	type PolicyContext = {
157	  customer: Customer;
158	  previousContracts: number;
159	};
160	
161	const POLICY_MODIFIER_RULES: Rule<PolicyContext>[] = [
162	  {
163	    appliesTo: ({ customer }) =>
164	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
165	    rate: LOYALTY_DISCOUNT_RATE,
166	  },
167	  {
168	    appliesTo: ({ previousContracts }) => previousContracts > 0,
169	    rate: FOLLOW_UP_DISCOUNT_RATE,
170	  },
171	];
172	
173	const totalPolicyModifierRateOf = (policy: PolicyContext): number =>
174	  INSURANCE_SURCHARGE_RATE + totalRateOf(POLICY_MODIFIER_RULES, policy);
175	
176	const quotePremium = (items: Item[], policy: PolicyContext): number => {
177	  const basePremium = totalBasePremiumOf(items);
178	
179	  return roundedUpInMHPCOsFavour(
180	    basePremium +
181	      totalItemSurchargeOf(items) +
182	      basePremium * totalPolicyModifierRateOf(policy) +
183	      PROCESSING_FEE,
184	  );
185	};
186	
187	const DEDUCTIBLE = 100;
188	const CAP_MULTIPLIER = 2;
189	
190	const insuranceSumOf = (items: Item[]): number =>
191	  sumOver(items, insuranceValueOf);
192	
193	const payoutCapOf = (items: Item[]): number =>
194	  CAP_MULTIPLIER * insuranceSumOf(items);
195	
196	const HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
197	const HALVED_REIMBURSEMENT_RATE = 0.5;
198	const FULL_REIMBURSEMENT_RATE = 1;
199	
200	const reimbursementRateFor = (item: Item): number =>
201	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
202	    ? HALVED_REIMBURSEMENT_RATE
203	    : FULL_REIMBURSEMENT_RATE;
204	
205	const payoutForDamage = (damage: Damage, item: Item): number =>
206	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;
207	
208	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
209	
210	type ClaimResult = {
211	  payout: number;
212	  remainingCap: number;
213	};
214	
215	// Each damage entry is settled against a distinct insured item, so a policy
216	// covering one sword cannot pay out for two damaged swords.
217	type Settlement = {
218	  total: number;
219	  unclaimedItems: Item[];
220	};
221	
222	const NOT_FOUND = -1;
223	
224	// A damage is claimable only if it is a real loss and the policy still has an
225	// unclaimed item of that type to settle it against. Answers with that item's
226	// position, so the caller can both pay for it and strike it off.
227	const claimedItemIndexFor = (
228	  damage: Damage,
229	  unclaimedItems: Item[],
230	): number => {
231	  if (damage.amount < 0) {
232	    throw new Error(`negative damage amount: ${damage.amount}`);
233	  }
234	
235	  const claimedAgainst = unclaimedItems.findIndex(
236	    (item) => item.type === damage.itemType,
237	  );
238	
239	  if (claimedAgainst === NOT_FOUND) {
240	    throw new Error(`damaged item not insured: ${damage.itemType}`);
241	  }
242	
243	  return claimedAgainst;
244	};
245	
246	const settleDamage = (
247	  { total, unclaimedItems }: Settlement,
248	  damage: Damage,
249	): Settlement => {
250	  const claimedAgainst = claimedItemIndexFor(damage, unclaimedItems);
251	
252	  return {
253	    total: total + payoutForDamage(damage, unclaimedItems[claimedAgainst]),
254	    unclaimedItems: unclaimedItems.filter(
255	      (_, index) => index !== claimedAgainst,
256	    ),
257	  };
258	};
259	
260	const totalPayoutFor = (damages: Damage[], insuredItems: Item[]): number =>
261	  damages.reduce(settleDamage, { total: 0, unclaimedItems: insuredItems })
262	    .total;
263	
264	// A claim never pays out more than the policy has left; whatever it does pay
265	// depletes the cap by exactly that much.
266	const drawnAgainstCap = (
267	  desiredPayout: number,
268	  remainingCap: number,
269	): ClaimResult => {
270	  const payout = roundedDownInMHPCOsFavour(
271	    Math.min(desiredPayout, remainingCap),
272	  );
273	
274	  return { payout, remainingCap: remainingCap - payout };
275	};
276	
277	const settleClaim = (incident: Incident, policy: IssuedPolicy): ClaimResult =>
278	  drawnAgainstCap(
279	    totalPayoutFor(incident.damages, policy.insuredItems),
280	    policy.remainingCap,
281	  );
282	
283	// A policy, once quoted, is referred to by later claim steps via its step index.
284	// Its cap depletes as claims are paid out against it.
285	type IssuedPolicy = {
286	  insuredItems: Item[];
287	  remainingCap: number;
288	};
289	
290	// Everything a step needs to know about the steps that came before it.
291	// Policies are keyed by the index of the quote step that issued them, which is
292	// how a claim step refers to them.
293	type ScenarioHistory = {
294	  issuedPolicies: Map<number, IssuedPolicy>;
295	  results: unknown[];
296	};
297	
298	const EMPTY_HISTORY: ScenarioHistory = {
299	  issuedPolicies: new Map(),
300	  results: [],
301	};
302	
303	// Every step both records a result and leaves exactly one policy changed:
304	// a quote issues one, a claim depletes the cap of the one it draws against.
305	const withStepRecorded = (
306	  history: ScenarioHistory,
307	  policyIndex: number,
308	  policy: IssuedPolicy,
309	  result: unknown,
310	): ScenarioHistory => ({
311	  issuedPolicies: new Map(history.issuedPolicies).set(policyIndex, policy),
312	  results: [...history.results, result],
313	});
314	
315	const takeQuoteStep = (
316	  step: QuoteStep,
317	  stepIndex: number,
318	  history: ScenarioHistory,
319	  customer: Customer,
320	): ScenarioHistory =>
321	  withStepRecorded(
322	    history,
323	    stepIndex,
324	    {
325	      insuredItems: step.items,
326	      remainingCap: payoutCapOf(step.items),
327	    },
328	    {
329	      premium: quotePremium(step.items, {
330	        customer,
331	        previousContracts: history.issuedPolicies.size,
332	      }),
333	    },
334	  );
335	
336	const issuedPolicyFor = (
337	  step: ClaimStep,
338	  issuedPolicies: Map<number, IssuedPolicy>,
339	): IssuedPolicy => {
340	  const policy = issuedPolicies.get(step.policy);
341	
342	  if (policy === undefined) {
343	    throw new Error(`claim against unknown policy: ${step.policy}`);
344	  }
345	
346	  return policy;
347	};
348	
349	const takeClaimStep = (
350	  step: ClaimStep,
351	  history: ScenarioHistory,
352	): ScenarioHistory => {
353	  const policy = issuedPolicyFor(step, history.issuedPolicies);
354	  const { payout, remainingCap } = settleClaim(step.incident, policy);
355	
356	  return withStepRecorded(
357	    history,
358	    step.policy,
359	    { ...policy, remainingCap },
360	    { payout, remainingCap },
361	  );
362	};
363	
364	export const runScenario = (scenario: Scenario): ScenarioResult => {
365	  const history = scenario.steps.reduce(
366	    (soFar, step, stepIndex) =>
367	      isQuote(step)
368	        ? takeQuoteStep(step, stepIndex, soFar, scenario.customer)
369	        : takeClaimStep(step, soFar),
370	    EMPTY_HISTORY,
371	  );
372	
373	  return { results: history.results };
374	};
